"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["85668"],{425443(e){e.exports=JSON.parse('{"id":13881,"title":"chute libre ","description":"Agis comme un professeur de physique exp\xe9riment\xe9 sp\xe9cialis\xe9 dans le programme de 2\u1D49 ann\xe9e du Baccalaur\xe9at marocain.\\n\\nPr\xe9pare un cours complet et p\xe9dagogique sur la chute libre, destin\xe9 \xe0 des \xe9l\xe8ves de 2\u1D49 Bac.\\n\\nLe document doit contenir :\\n\\nUne introduction simple expliquant la notion de chute libre.\\nLa d\xe9finition scientifique de la chute libre.\\nLes conditions de la chute libre (absence de frottements de l\'air).\\nL\'\xe9tude des forces appliqu\xe9es sur un corps en chute libre.\\nL\'application de la deuxi\xe8me loi de Newton.\\nLa d\xe9monstration de l\'acc\xe9l\xe9ration de la pesanteur g=9,81m/s\\n2\\n.\\nLes \xe9quations horaires de la vitesse et de la position.\\nLa chute libre sans vitesse initiale.\\nLa chute libre avec vitesse initiale vers le haut et vers le bas.\\nDes sch\xe9mas d\xe9taill\xe9s en ASCII repr\xe9sentant :\\nle bilan des forces ;\\nle mouvement de chute ;\\nles vecteurs vitesse et acc\xe9l\xe9ration ;\\nles graphiques position-temps, vitesse-temps et acc\xe9l\xe9ration-temps.\\nDes exemples d\'applications dans la vie quotidienne.\\nDeux exercices corrig\xe9s niveau Bac.\\nUn r\xe9sum\xe9 final sous forme de fiche de r\xe9vision.\\nUn tableau r\xe9capitulatif des formules \xe0 conna\xeetre.\\n\\nPr\xe9sente le cours avec des titres clairs, des explications simples, des encadr\xe9s de formules, des sch\xe9mas bien d\xe9taill\xe9s et une mise en page adapt\xe9e \xe0 un expos\xe9 scolaire de 5 \xe0 10 pages","remark":"donner un cours ","owner":"elhaite","upvotes":1,"downvotes":0,"upvoteDifference":1,"updatedAt":"2026-06-16T00:37:09.651Z"}')}}]);